<script setup lang="ts">
import { computed } from 'vue'
import type { Detail } from '../../api/workbench'
import { workflowContext, currentDestination } from '../../workflow-context'
import { session } from '../../session'
import { workflowStages, purposeFor, workflowDestination } from '../../workbench-guidance'
import AppIcon from '../AppIcon.vue'
const props = defineProps<{ dataset: Detail; versionId: string; compact?: boolean }>()
const emit = defineEmits<{ clean: [] }>()
const selectedModel = computed(() => workflowContext.dataset?.datasetId === props.dataset.datasetId && workflowContext.version === props.versionId ? workflowContext.model : undefined)
const target = (step: string) => selectedModel.value ? currentDestination(step) : workflowDestination(props.dataset,props.versionId,step)
const stages = computed(() => workflowStages(props.dataset, props.versionId, selectedModel.value).filter(step => session.user?.role === 'ADMIN' || !['prepare','train'].includes(step.key)))
const clean = computed(() => { const v = props.dataset.versions.find(v => v.versionId === props.versionId); return v?.stage === 'CLEAN' && v.status === 'READY' ? v : props.dataset.versions.find(v => v.stage === 'CLEAN' && v.status === 'READY' && v.parentVersionId === props.versionId) })
const purpose = computed(() => purposeFor(props.dataset.kind, props.dataset.purpose))
const labels = { done: '已完成', active: '处理中', waiting: '待进行', error: '需处理' }
</script>
<template><section class="dataset-journey" aria-label="数据处理流程"><div class="journey-heading"><strong>这批数据的处理流程</strong><span>点击阶段查看结果或继续操作</span></div><ol class="journey-steps"><li v-for="step in stages" :key="step.key" :class="step.status"><RouterLink :to="target(step.key)"><span class="journey-icon"><AppIcon :name="step.status === 'done' ? 'check' : step.icon" :size="18" /></span><strong>{{ step.label }}</strong><small>{{ labels[step.status] }}</small><span>{{ step.description }}</span></RouterLink></li></ol><div v-if="!compact" class="work-actions"><template v-if="clean"><RouterLink v-if="purpose === 'LIBRARY' || purpose === 'BOTH'" class="link-button" :to="workflowDestination(dataset,versionId,'library')"><AppIcon name="library" :size="16" />查看与继续入库</RouterLink><RouterLink v-if="session.user?.role === 'ADMIN' && (purpose === 'TRAIN' || purpose === 'BOTH')" class="link-button" :to="workflowDestination(dataset,versionId,'train')"><AppIcon name="train" :size="16" />准备样本与训练</RouterLink></template><el-button v-else :disabled="dataset.archived || stages.some(s => s.status === 'active')" type="primary" @click="emit('clean')">下一步：{{ ['LIBRARY','BOTH'].includes(purpose) ? '清洗并提交入库' : '生成清洗版本' }}</el-button><span v-if="!clean && ['LIBRARY','BOTH'].includes(purpose)" class="help-line">清洗完成后自动创建入库任务，审核员提交的材料需管理员批准。</span></div></section></template>
<style scoped>.dataset-journey{background:var(--canvas);border:1px solid var(--line);padding:22px;margin-bottom:20px}.journey-heading{display:flex;gap:16px;align-items:center;justify-content:space-between;margin-bottom:22px;flex-wrap:wrap}.journey-heading>span{font-size:12px;color:var(--muted)}.journey-steps{display:flex;list-style:none;padding:0;margin:0;overflow-x:auto;gap:0}.journey-steps li{flex:1;min-width:110px;position:relative}.journey-steps li:not(:last-child):after{content:'';position:absolute;top:17px;left:36px;right:4px;border-top:1px solid var(--line)}.journey-steps a{display:grid;gap:5px;text-decoration:none;padding:0 8px 8px;color:var(--muted)}.journey-icon{display:grid;place-items:center;width:34px;height:34px;background:var(--soft);border:1px solid var(--line);margin-bottom:7px;z-index:1}.journey-steps strong{font-size:12px;color:var(--heading)}.journey-steps small{font-size:11px}.journey-steps a>span:last-child{font-size:10px;line-height:1.7}.done .journey-icon{color:var(--el-color-success);border-color:var(--el-color-success)}.active .journey-icon{color:var(--el-color-primary);border-color:var(--el-color-primary);background:color-mix(in srgb,var(--el-color-primary) 8%,var(--canvas))}.error .journey-icon{color:var(--el-color-danger);border-color:var(--el-color-danger)}.journey-steps a:hover strong{text-decoration:underline}</style>
